CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key AUTO_INCREMENT not null, "name" varchar not null, "email" varchar not null, "password" varchar not null, "role" varchar check ("role" in ('client', 'agent', 'admin')) not null default 'client', "department" varchar, "avatar" varchar, "last_login_at" datetime, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "is_active" tinyint(1) not null default '1', "phone" varchar, "bio" text);
