CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key AUTO_INCREMENT not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key AUTO_INCREMENT not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "ticket_replies" ("id" integer primary key AUTO_INCREMENT not null, "ticket_id" integer not null, "user_id" integer not null, "body" text not null, "is_internal" tinyint(1) not null default '0', "is_solution" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("ticket_id") references "tickets"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "attachments" ("id" integer primary key AUTO_INCREMENT not null, "ticket_id" integer not null, "ticket_reply_id" integer, "user_id" integer not null, "filename" varchar not null, "path" varchar not null, "mime_type" varchar not null, "size" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("ticket_id") references "tickets"("id") on delete cascade, foreign key("ticket_reply_id") references "ticket_replies"("id") on delete set null, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "ticket_histories" ("id" integer primary key AUTO_INCREMENT not null, "ticket_id" integer not null, "user_id" integer not null, "action" varchar not null, "old_value" varchar, "new_value" varchar, "comment" text, "created_at" datetime, "updated_at" datetime, foreign key("ticket_id") references "tickets"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "tags" ("id" integer primary key AUTO_INCREMENT not null, "name" varchar not null, "color" varchar not null default '#6B7280', "created_at" datetime, "updated_at" datetime);
