CREATE TABLE IF NOT EXISTS "ticket_tag" ("ticket_id" integer not null, "tag_id" integer not null, foreign key("ticket_id") references "tickets"("id") on delete cascade, foreign key("tag_id") references "tags"("id") on delete cascade, primary key ("ticket_id", "tag_id"));
CREATE TABLE IF NOT EXISTS "tickets" ("id" integer primary key AUTO_INCREMENT not null, "reference" varchar not null, "user_id" integer not null, "assigned_to" integer, "title" varchar not null, "description" text not null, "status" varchar check ("status" in ('open', 'in_progress', 'waiting_client', 'resolved', 'closed')) not null default 'open', "priority" varchar check ("priority" in ('low', 'medium', 'high', 'critical')) not null default 'medium', "category" varchar check ("category" in ('bug', 'feature_request', 'access', 'hardware', 'software', 'network', 'other')) not null default 'other', "department" varchar, "first_response_at" datetime, "resolved_at" datetime, "closed_at" datetime, "due_at" datetime, "satisfaction_rating" integer, "satisfaction_comment" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("assigned_to") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "comments" ("id" integer primary key AUTO_INCREMENT not null, "message" text not null, "ticket_id" integer not null, "user_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("ticket_id") references "tickets"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
